CREATE DATABASE IF NOT EXISTS librarie;
USE librarie;
CREATE TABLE IF NOT EXISTS books(id BIGINT PRIMARY KEY AUTO_INCREMENT,isbn VARCHAR(32) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,description TEXT,published_year SMALLINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS members(id BIGINT PRIMARY KEY AUTO_INCREMENT,member_number VARCHAR(32) NOT NULL UNIQUE,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,phone VARCHAR(40),status ENUM('ACTIVE','SUSPENDED','CLOSED') NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory(id BIGINT PRIMARY KEY AUTO_INCREMENT,book_id BIGINT NOT NULL,barcode VARCHAR(64) NOT NULL UNIQUE,circulation_status ENUM('AVAILABLE','ON_LOAN','LOST','DAMAGED') NOT NULL DEFAULT 'AVAILABLE',shelf_location VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(book_id) REFERENCES books(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS loans(id BIGINT PRIMARY KEY AUTO_INCREMENT,inventory_id BIGINT NOT NULL,member_id BIGINT NOT NULL,checked_out_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,due_at TIMESTAMP NOT NULL,returned_at TIMESTAMP NULL,status ENUM('OPEN','RETURNED','OVERDUE') NOT NULL DEFAULT 'OPEN',FOREIGN KEY(inventory_id) REFERENCES inventory(id),FOREIGN KEY(member_id) REFERENCES members(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fines(id BIGINT PRIMARY KEY AUTO_INCREMENT,member_id BIGINT NOT NULL,loan_id BIGINT NULL,amount DECIMAL(10,2) NOT NULL,status ENUM('OPEN','PAID','WAIVED') NOT NULL DEFAULT 'OPEN',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id),FOREIGN KEY(loan_id) REFERENCES loans(id)) ENGINE=InnoDB;
